declarations:
// already implemented here, and only the grader uses them: raw_push()
// ต่อสมาชิกท้ายอาเรย์โดยไม่เรียก fixUp และ raw_swap() สลับช่องสองช่อง
// โดยไม่ซ่อมอะไรเลย ทั้งสองจึงทำให้อาเรย์หยุดเป็นฮีปได้
void raw_push(const T &element)
{
  ensureCapacity(mSize + 1);
  mData[mSize] = element;
  mSize++;
}

void raw_swap(size_t i, size_t j)
{
  T hold = mData[i];
  mData[i] = mData[j];
  mData[j] = hold;
}
